-- Daily challenges for 2026-10-23: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-23. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('being-kind-online', 'Being Kind Online', 'For anyone who wants their time on screens to feel friendlier. Each day is one small way to bring warmth and care to messages, comments and group chats, from a sincere compliment to pausing before a heated reply.', 'Kindness', 365, array['Relationships', 'Values', 'Communication']::text[], 1, '2026-10-23T17:00:00+00:00'::timestamptz),
  ('breathing-a-little-easier', 'Breathing a Little Easier', 'For anyone who notices they hold their breath or breathe fast when life gets busy. Each day is one short, gentle breathing practice, a few slow breaths at a desk, in a line or at bedtime, so calm has an easy way in.', 'Grounding', 365, array['Stress', 'Mindfulness', 'Anxiety']::text[], 1, '2026-10-23T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('being-kind-online', 'breathing-a-little-easier');

