  ('being-kind-online', 237, 'Put a hard message in drafts overnight and read it once more with fresh eyes before sending.'),
  ('being-kind-online', 238, 'Ask a trusted friend to read a touchy reply before you send it.'),
  ('being-kind-online', 239, 'Pick a phone call over a long text when a conversation is getting tense.'),
  ('being-kind-online', 240, 'Write "I might be misreading this, but" before raising a concern about a message.'),
  ('being-kind-online', 241, 'Imagine three kind explanations for a short reply before reacting to it.'),
  ('being-kind-online', 242, 'Respond to a challenging opinion with a genuine question before stating your own.'),
  ('being-kind-online', 243, 'Agree with what you can in a heated thread and say so plainly.'),
  ('being-kind-online', 244, 'Step away from a group chat argument with "I''m going to sit this one out."'),
  ('being-kind-online', 245, 'Leave an online debate quietly when it turns into name-calling.'),
  ('being-kind-online', 246, 'Resist adding a laughing emoji to a post that mocks someone.'),
  ('being-kind-online', 247, 'Choose not to join a pile-on, even if the person made a real mistake.'),
  ('being-kind-online', 248, 'Keep someone''s embarrassing old post to yourself instead of digging it up.'),
  ('being-kind-online', 249, 'Stop a rumor in a group chat by saying, "I don''t think we should spread that."'),
  ('being-kind-online', 250, 'Search for a fact-check before forwarding a shocking headline.'),
  ('being-kind-online', 251, 'Read past the headline of an article before you share it.'),
  ('being-kind-online', 252, 'Look up the date on an old news story before sharing it as if it were new.'),
  ('being-kind-online', 253, 'Name the source when you repost a quote, and check that the person really said it.'),
  ('being-kind-online', 254, 'Link back to the creator''s page whenever you share their art.'),
  ('being-kind-online', 255, 'Write image descriptions for every photo in one post, including the colors and mood.'),
  ('being-kind-online', 256, 'Use clear, high-contrast text when you make a graphic to share, so more people can read it.'),
  ('being-kind-online', 257, 'Put emojis at the end of a sentence, not between words, so screen readers can read it smoothly.'),
  ('being-kind-online', 258, 'Spell out an abbreviation the first time you use it in a group message.'),
  ('being-kind-online', 259, 'Write times with a time zone, like "2 p.m. Eastern," when you invite people from other places.'),
  ('being-kind-online', 260, 'Speak kindly about a stranger whose post you disagree with when you discuss it with friends.'),
  ('being-kind-online', 261, 'Describe a customer or patient in a work chat with respect, even when they were difficult.'),
  ('being-kind-online', 262, 'Say sorry to a friend in a text for a joke that went too far, and ask how it made them feel.'),
  ('being-kind-online', 263, 'Make amends for a harsh review by updating it after the business made things right.'),
  ('being-kind-online', 264, 'Mute a relative''s posts for a while if they keep upsetting you, without unfriending them.'),
  ('being-kind-online', 265, 'Block a stranger who sends you unwanted pictures or messages, and report the account.'),
  ('being-kind-online', 266, 'Take a break from a group chat that has turned hurtful, and tell one friend in it why.'),
  ('being-kind-online', 267, 'Leave any conversation where someone is pressuring you to share personal photos or information.'),
  ('being-kind-online', 268, 'Write to a friend who seems lonely online and suggest a time to talk soon.'),
  ('being-kind-online', 269, 'Check in with a coworker who has been quieter than usual in team chat with a private "How''s it going?"'),
  ('being-kind-online', 270, 'Text a grandparent a short message telling them one thing you learned from them.'),
  ('being-kind-online', 271, 'Reply to an elderly relative''s long post with patience and real interest.'),
  ('being-kind-online', 272, 'Celebrate a friend''s sober or debt-free anniversary with a warm comment, if they''ve shared it publicly.'),
  ('being-kind-online', 273, 'Send a congratulations message to someone who got into a school or program they wanted.'),
  ('being-kind-online', 274, 'Mention people by name when you thank a group in a video meeting.'),
  ('being-kind-online', 275, 'Turn off notifications during a video call so you can listen fully to the speaker.'),
  ('being-kind-online', 276, 'Wave and say goodbye at the end of a video call instead of just dropping off.'),
  ('being-kind-online', 277, 'Tell a colleague privately if their microphone is echoing on a call, kindly and quickly.'),
