  ('being-kind-online', 279, 'Use "Thank you for your patience" instead of "Sorry for the delay" in one email today.'),
  ('being-kind-online', 280, 'Add the key detail to your email subject line so the reader can find it later.'),
  ('being-kind-online', 281, 'Share credit with your team in a group email when you get praise for joint work.'),
  ('being-kind-online', 282, 'Mute your mic while gaming when you feel your temper rising.'),
  ('being-kind-online', 283, 'Offer a new player in a game your spare items or a quick walkthrough.'),
