  ('being-kind-online', 331, 'Thank someone for writing in your language when it''s their second one, and reply simply.'),
  ('being-kind-online', 332, 'Choose kind words about any group of people you don''t belong to in what you post today.'),
  ('being-kind-online', 333, 'Rewrite a post about a frustrating stranger so it shares the lesson, not their identity.'),
  ('being-kind-online', 334, 'Say sorry for a misunderstanding in an email thread, taking your share of it.'),
  ('being-kind-online', 335, 'Apologize to a teammate for snapping in voice chat, at the start of the next round.'),
  ('being-kind-online', 336, 'Quietly mute an old acquaintance whose posts stir up envy, and wish them well.'),
