  ('being-kind-online', 347, 'Keep side chats kind during a video meeting, with nothing you wouldn''t say aloud.'),
  ('being-kind-online', 348, 'Give your name and a friendly hello when you join a video call with new people.'),
  ('being-kind-online', 349, 'Thank people for coming at the end of a video call you hosted.'),
  ('being-kind-online', 350, 'Reply to an email with "Thanks, got it" so the sender isn''t left wondering.'),
  ('being-kind-online', 351, 'Use a kind closing line in a difficult email, like "I appreciate you working through this with me."'),
  ('being-kind-online', 352, 'Write a thank-you email to a recruiter or interviewer, even if you didn''t get the job.'),
