  ('being-kind-online', 354, 'Thank the person who organized an online game night or tournament.'),
  ('being-kind-online', 355, 'Teach a new player one shortcut, slowly, without taking over their turn.'),
  ('being-kind-online', 356, 'Post an encouraging message in an online class forum before an exam.'),
