  ('breathing-a-little-easier', 226, 'Feel the air cool your upper lip as you breathe in and warm it as you breathe out, six breaths.'),
  ('breathing-a-little-easier', 227, 'Close your laptop for three breaths before you start a new piece of work.'),
  ('breathing-a-little-easier', 228, 'Trace a square on your knee with one finger: up for in, across for rest, down for out, across for rest, four squares.'),
  ('breathing-a-little-easier', 229, 'Let your breathing stay light and natural today; even two slow breaths count as the practice.'),
  ('breathing-a-little-easier', 230, 'Rest your hand on your collarbone and feel the gentle lift as you breathe in, five times.'),
  ('breathing-a-little-easier', 231, 'Breathe out for a count of five, then let the in-breath come by itself, five times.'),
