  ('breathing-a-little-easier', 233, 'Notice how your body feels in the quiet moment after you breathe out, four times.'),
  ('breathing-a-little-easier', 234, 'Breathe in for three steps and out for three steps as you walk to the mailbox and back.'),
  ('breathing-a-little-easier', 235, 'Sweep your arms up in front of you as you breathe in and down as you breathe out, slow and easy, four times.'),
